<script setup>
import { ref, onMounted } from 'vue'
import { api, downloadCsv } from './api'
import ReportPage from './ReportPage.vue'
const me=ref(null), username=ref(''), password=ref(''), tab=ref('reports'), error=ref(''), busy=ref(false)
const stores=ref([]), products=ref([]), orders=ref({items:[],total:0,page:1,size:20}), batches=ref([]), selected=ref(null), audit=ref([]), detail=ref(null), file=ref(null)
const filters=ref({storeId:'',from:'',to:'',status:''}), page=ref(1), appliedOrders=ref({})
const labels={PAID:'已支付',CANCELLED:'已取消',REFUNDED:'全额退款',READY:'待确认',INVALID:'预检查未通过',SUCCEEDED:'导入成功',FAILED:'导入失败'}
const money=n=>new Intl.NumberFormat('zh-CN',{style:'currency',currency:'CNY'}).format(n/100)
const time=t=>t?t.replace('T',' '):'—'
function resetSession(){me.value=null;stores.value=[];products.value=[];orders.value={items:[],total:0,page:1,size:20};batches.value=[];selected.value=null;audit.value=[];detail.value=null;file.value=null;filters.value={storeId:'',from:'',to:'',status:''};appliedOrders.value={};page.value=1;tab.value='reports'}
async function run(fn){busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message;if(e.status===401)resetSession();if(e.detail?.id)selected.value=e.detail}finally{busy.value=false}}
async function loadOrders(){const f={...filters.value};const p=new URLSearchParams({page:page.value,size:20});for(const [k,v] of Object.entries(f))if(v)p.set(k,v);orders.value=await api(`/orders?${p}`);appliedOrders.value=f}
async function exportOrders(){await run(async()=>{const p=new URLSearchParams(Object.entries(appliedOrders.value).filter(([,v])=>v!==''));await downloadCsv(`/orders/export?${p}`,'order-ledger.csv')})}
async function loadBatches(){batches.value=(await api('/imports')).items}
async function init(){me.value=await api('/auth/me');[stores.value,products.value]=await Promise.all([api('/stores'),api('/products')]);await loadOrders();await loadBatches()}
async function login(){await run(async()=>{await api('/auth/login',{method:'POST',body:new URLSearchParams({username:username.value,password:password.value})});password.value='';resetSession();await init()})}
async function logout(){await run(async()=>{await api('/auth/logout',{method:'POST'});resetSession()})}
async function check(){await run(async()=>{if(!file.value)throw new Error('请先选择 CSV 文件');selected.value=null;audit.value=[];const body=new FormData();body.append('file',file.value);selected.value=await api('/imports/precheck',{method:'POST',body});await loadBatches()})}
async function confirm(){await run(async()=>{const id=selected.value.id;try{selected.value=await api(`/imports/${id}/confirm`,{method:'POST'})}finally{selected.value=await api(`/imports/${id}`);await loadBatches()}await loadOrders();audit.value=await api(`/imports/${id}/audit`)})}
async function choose(b){await run(async()=>{selected.value=await api(`/imports/${b.id}`);audit.value=await api(`/imports/${b.id}/audit`)})}
onMounted(async()=>{try{await init()}catch(e){if(e.status!==401)error.value=e.message}})
</script>

<template>
  <div v-if="!me" class="login-shell">
    <div class="intro"><span class="eyebrow">ORDER REPORTING / 门店经营</span><h1>每一笔订单，<br>都有据可查。</h1><p>从 CSV 校验到原始明细，<br>让门店数据有清楚的来处。</p><div class="steps">01 预检查　→　02 确认导入　→　03 核对订单</div></div>
    <form class="login-card" @submit.prevent="login"><span class="eyebrow">欢迎回来</span><h2>登录经营后台</h2><p class="muted">管理员可查看全部门店；门店账号仅限本店。</p><label>账号<input v-model="username" autocomplete="username" required placeholder="admin / store1 / store2"></label><label>密码<input v-model="password" type="password" autocomplete="current-password" required></label><p v-if="error" class="error" role="alert">{{error}}</p><button :disabled="busy" class="primary">{{busy?'正在登录…':'登录'}}</button><small>本地演示账号密码见项目 .env 文件。</small></form>
  </div>
  <div v-else class="workspace">
    <aside><div class="brand"><span class="brand-icon">单</span><div>门店经营<span>ORDER REPORTING</span></div></div><p class="nav-caption">工作台</p><button :class="{active:tab==='reports'}" @click="tab='reports'">▥　经营报表</button><button :class="{active:tab==='orders'}" @click="tab='orders'">▤　订单台账</button><button :class="{active:tab==='imports'}" @click="tab='imports'">↥　数据导入</button><div class="aside-note"><span class="dot"></span> M2 · 经营报表<p>上海时间 · 金额精确到分</p></div></aside>
    <div class="main"><header><span>经营后台 / {{tab==='reports'?'经营报表':tab==='orders'?'订单台账':'数据导入'}}</span><div>{{me.username}} <span class="badge">{{me.role==='ADMIN'?'管理员':'门店账号'}}</span><button class="text-button" @click="logout" :disabled="busy">退出</button></div></header>
      <main><p v-if="error" class="error" role="alert">{{error}}</p><ReportPage v-if="tab==='reports'" :me="me" :stores="stores" @detail="id=>run(async()=>{detail=await api(`/orders/${id}`)})" @expired="resetSession"/><div v-if="tab!=='reports'" class="title-row"><div><span class="eyebrow">{{tab==='orders'?'ORDER LEDGER':'DATA IMPORT'}}</span><h1>{{tab==='reports'?'经营报表':tab==='orders'?'订单台账':'数据导入'}}</h1><p class="muted">{{tab==='orders'?'查看原始订单，逐笔核对支付与退款时间。':'先检查文件，再确认入库；任一行错误都会阻止整批导入。'}}</p></div><span class="scope-tag">{{me.role==='ADMIN'?'全部门店权限':stores[0]?.name}}</span></div>
      <template v-if="tab==='orders'">
        <form class="panel filter-row" @submit.prevent="run(async()=>{page=1;await loadOrders()})"><label>门店<select v-model="filters.storeId"><option value="">{{me.role==='ADMIN'?'全部门店':'本门店'}}</option><option v-for="s in stores" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>下单开始日期<input v-model="filters.from" type="date"></label><label>下单结束日期<input v-model="filters.to" type="date"></label><label>订单状态<select v-model="filters.status"><option value="">全部状态</option><option v-for="s in ['PAID','CANCELLED','REFUNDED']" :key="s" :value="s">{{labels[s]}}</option></select></label><button class="primary" :disabled="busy">查询</button></form>
        <div class="panel"><div class="panel-heading"><h3>订单记录 <span class="count">{{orders.total}}</span></h3><div><small>按下单时间倒序 · 每页 20 条</small><button :disabled="busy" @click="exportOrders">导出本次查询 CSV</button></div></div><div class="table-scroll"><table><thead><tr><th>订单号 / 门店</th><th>下单时间</th><th>状态</th><th class="numeric">订单金额</th><th></th></tr></thead><tbody><tr v-for="o in orders.items" :key="o.id"><td><strong>{{o.externalId}}</strong><small>{{o.storeName}}</small></td><td>{{time(o.orderedAt)}}</td><td><span class="badge" :class="o.status">{{labels[o.status]}}</span></td><td class="numeric amount">{{money(o.totalCents)}}</td><td><button class="text-button" :disabled="busy" @click="run(async()=>{detail=await api(`/orders/${o.id}`)})">查看明细 →</button></td></tr></tbody></table></div><div v-if="!orders.items.length" class="empty"><b>暂无符合条件的订单</b><p>调整筛选条件，或前往数据导入上传第一份文件。</p><button @click="tab='imports'">前往导入</button></div><div class="pagination"><span>第 {{orders.page}} 页 · 共 {{orders.total}} 条</span><div><button :disabled="busy||page<=1" @click="run(async()=>{page--;await loadOrders()})">上一页</button><button :disabled="busy||page*20>=orders.total" @click="run(async()=>{page++;await loadOrders()})">下一页</button></div></div></div>
        <p class="footnote">本页按下单日期筛选，订单金额包含取消与退款订单的原始金额，不代表净销售额。支付和退款事件分别保留。导出使用已应用的筛选，修改条件后请先查询；上限 10,000 单。</p>
      </template>
      <template v-else-if="tab==='imports'">
        <div class="import-grid"><section class="panel import-form"><div class="panel-heading"><h3>01 / 上传与预检查</h3><a href="/api/imports/template">下载 CSV 表头</a></div><p class="muted">UTF-8 · 最多 5,000 条明细 · 1 MiB</p><label class="file-box">选择订单 CSV<input type="file" accept=".csv,text/csv" @change="file=$event.target.files[0];selected=null;audit=[]"></label><button class="primary" :disabled="busy||!file" @click="check">{{busy?'处理中…':'开始预检查'}}</button><div class="catalog-hint"><b>可用编码</b><p>门店：{{stores.map(s=>s.code+' '+s.name).join(' / ')}}</p><p>商品：{{products.map(p=>p.code+' '+p.name).join(' / ')}}</p></div><p class="footnote">固定 12 列；同一订单各行需重复填写相同的订单总额和时间。修改后重新上传，产生新的批次。</p></section>
        <section class="panel import-result"><div class="panel-heading"><h3>02 / 检查与确认</h3><span v-if="selected" class="badge" :class="selected.status">{{labels[selected.status]}}</span></div><div v-if="!selected" class="empty"><b>等待预检查结果</b><p>预检查不会写入订单。</p></div><template v-else><small class="batch-id">批次 {{selected.id}}</small><div class="metrics"><div><strong>{{selected.rowCount}}</strong><span>明细记录</span></div><div><strong>{{selected.orderCount}}</strong><span>识别订单</span></div><div><strong>{{selected.insertedCount}}</strong><span>已新增</span></div><div><strong>{{selected.skippedCount}}</strong><span>已跳过</span></div></div><div v-if="selected.errors.length" class="errors-list" role="alert"><p v-for="(e,i) in selected.errors" :key="i"><b>{{e.line?'第 '+e.line+' 行':'批次'}}：</b>{{e.reason}}</p><small>最多显示 100 条错误；行号为 CSV 物理起始行，表头为第 1 行。</small></div><p v-else class="success">{{selected.status==='SUCCEEDED'?'整批已提交。重复确认不会增加销量。':'预检查通过。确认时后端会再次校验。'}}</p><button v-if="['READY','FAILED'].includes(selected.status)" class="primary" :disabled="busy" @click="confirm">{{selected.status==='FAILED'?'重新校验并重试':'确认整批导入'}}</button><div v-if="audit.length" class="audit"><h4>操作记录</h4><p v-for="(a,i) in audit" :key="i">{{time(a.created_at)}} · {{a.action}} · {{a.detail}}</p></div></template></section></div>
        <section class="panel"><div class="panel-heading"><h3>我的最近批次</h3><button class="text-button" :disabled="busy" @click="run(loadBatches)">刷新</button></div><div class="table-scroll"><table><thead><tr><th>批次</th><th>创建时间</th><th>状态</th><th>新增 / 跳过</th><th></th></tr></thead><tbody><tr v-for="b in batches" :key="b.id"><td class="mono">{{b.id.slice(0,8)}}</td><td>{{time(b.createdAt)}}</td><td><span class="badge" :class="b.status">{{labels[b.status]}}</span></td><td>{{b.insertedCount}} / {{b.skippedCount}}</td><td><button class="text-button" :disabled="busy" @click="choose(b)">查看</button></td></tr></tbody></table></div><p v-if="!batches.length" class="empty">尚无导入批次</p><p class="footnote">显示当前账号最近 30 个批次。相同文件返回原批次；相同订单的不同内容会被拒绝。</p></section>
      </template></main>
    </div>
    <div v-if="detail" class="overlay" @click.self="detail=null"><section class="detail-panel" role="dialog" aria-modal="true" aria-labelledby="detail-title"><button class="close" @click="detail=null" aria-label="关闭详情">×</button><span class="eyebrow">ORDER DETAILS</span><h2 id="detail-title">{{detail.order.externalId}}</h2><p>{{detail.order.storeName}} · {{labels[detail.order.status]}}</p><dl><dt>下单时间</dt><dd>{{time(detail.order.orderedAt)}}</dd><dt>支付时间</dt><dd>{{time(detail.order.paidAt)}}</dd><dt>退款时间</dt><dd>{{time(detail.order.refundedAt)}}</dd><dt>原始金额</dt><dd>{{money(detail.order.totalCents)}}</dd></dl><table><thead><tr><th>商品</th><th>数量</th><th>单价</th><th>金额</th></tr></thead><tbody><tr v-for="i in detail.items" :key="i.lineNo"><td>{{i.productName}}<small>{{i.productCode}} · 行 {{i.lineNo}}</small></td><td>{{i.quantity}}</td><td>{{money(i.unitCents)}}</td><td>{{money(i.lineCents)}}</td></tr></tbody></table><p class="footnote">来源批次：{{detail.order.batchId}}</p><p class="notice">跨日退款计在退款日，原支付日销售保留。取消订单没有支付和退款事件。</p></section></div>
  </div>
</template>
